starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

starter.variables.tf:
variable "table_name" {
  description = "Input variable table_name."
  type        = string
  default     = "items"
}

variable "aws_region" {
  description = "Input variable aws_region."
  type        = string
  default     = "us-east-1"
}

starter.main.tf:
provider "aws" {
  region = var.aws_region
}

resource "aws_dynamodb_table" "this" {
  # TODO - Complete the aws_dynamodb_table resource.
  # Add the arguments and nested blocks required for aws_dynamodb_table.
}
